export const sources: Record<string, string> = {
    "api": "import { showLogin } from './screens.js'\n\nexport async function api(path, options) {\n  const settings = Object.assign({ credentials: 'same-origin' }, options || {})\n  settings.headers = Object.assign({}, settings.headers || {})\n  if (settings.body && typeof settings.body !== 'string') {\n    settings.headers['Content-Type'] = 'application/json'\n    settings.body = JSON.stringify(settings.body)\n  }\n  const response = await fetch(path, settings)\n  let value = null\n  try { value = await response.json() } catch {}\n  if (!response.ok) {\n    if (response.status === 401 && path.indexOf('/v1/admin/') === 0) showLogin()\n    const message = value && value.error ? value.error : '请求失败（HTTP ' + response.status + '）'\n    const error = new Error(localizeError(message))\n    error.status = response.status\n    throw error\n  }\n  return value\n}\n\nexport function localizeError(message) {\n  const messages = {\n    'Invalid Console Password': '控制台密码不正确',\n    'Console setup is required': '请先完成控制台初始化',\n    'Console setup is already complete': '控制台已完成初始化',\n    'Console Password confirmation does not match': '两次输入的控制台密码不一致',\n    'Console Password must contain at least 12 characters': '控制台密码至少需要 12 个字符',\n    'Console Password must not exceed 1024 bytes': '控制台密码不能超过 1024 字节',\n    'Console Password must not contain NUL bytes': '控制台密码包含不支持的字符',\n    'Current Console Password is incorrect': '当前控制台密码不正确',\n    'Gateway setup is required': '请先完成网关初始化',\n    'Admin session is required': '管理员会话已失效，请重新登录',\n    'Bearer API Key is required': '缺少 Bearer API 密钥',\n    'Invalid API Key': 'API 密钥无效',\n    'API Key is not authorized for this agent': '该 API 密钥无权访问此智能体',\n    'API Key already exists': 'API 密钥已存在',\n    'API Key not found': '未找到 API 密钥',\n    'API Key name is required': '请输入 API 密钥名称',\n    'API Key name is too long': 'API 密钥名称过长',\n    'Custom API Key must contain at least 16 characters': '自定义 API 密钥至少需要 16 个字符',\n    'Custom API Key must not exceed 512 bytes': '自定义 API 密钥不能超过 512 字节',\n    'Custom API Key contains an unsupported value': '自定义 API 密钥包含不支持的内容',\n    'workspaceRoots must contain at least one path': '至少需要保留一个工作区根目录',\n    'A2A authentication value is required': '请输入 A2A 认证凭据',\n    'A2A authentication value is invalid': 'A2A 认证凭据无效',\n    'A2A Agent Card URL is required': '请输入 Agent Card URL',\n    'A2A Agent Card URL is invalid': 'Agent Card URL 无效',\n    'A2A Agent Card URL must use http(s) without credentials or a fragment': 'Agent Card URL 必须使用 HTTP(S)，且不能包含凭据或片段',\n    'preferredTransport must be auto, jsonrpc, or http-json': '首选传输必须是自动、JSON-RPC 或 HTTP+JSON',\n    'A valid A2A header name is required': '请输入有效的 A2A 请求头名称',\n    'Too many authentication attempts': '认证失败次数过多，请稍后再试',\n    'Request body is too large': '请求内容过大',\n    'Request requires application/json': '请求必须使用 application/json',\n    'Same-origin request is required': '此操作必须从当前控制台页面发起',\n    'Request origin is invalid': '请求来源无效',\n    'Cross-origin admin request is not allowed': '不允许跨域管理请求',\n    'Control plane is unavailable': '管理控制面当前不可用',\n    'Agent Nexus run not found': '未找到运行记录',\n    'Internal server error': '服务器内部错误'\n  }\n  if (messages[message]) return messages[message]\n  const missingAgent = /^Configured agent not found: (.+)$/.exec(message)\n  if (missingAgent) return '未找到已配置的智能体：' + missingAgent[1]\n  const timeout = /^timeout must be between (\\d+) and (\\d+)$/.exec(message)\n  if (timeout) return '超时时间必须介于 ' + Math.round(Number(timeout[1]) / 1000) + ' 和 ' + Math.round(Number(timeout[2]) / 1000) + ' 秒之间'\n  const runtimeRange = /^(sessionTtlMs|promptTimeoutMs|cleanupIntervalMs) must be between (\\d+) and (\\d+)$/.exec(message)\n  if (runtimeRange) {\n    const units = {\n      sessionTtlMs: ['Session 空闲有效期', '小时', 3_600_000],\n      promptTimeoutMs: ['ACP 任务超时', '分钟', 60_000],\n      cleanupIntervalMs: ['清理任务周期', '秒', 1000]\n    }\n    const [label, unit, divisor] = units[runtimeRange[1]]\n    return label + '必须介于 ' + Math.round(Number(runtimeRange[2]) / divisor) + ' 和 ' + Math.round(Number(runtimeRange[3]) / divisor) + ' ' + unit + '之间'\n  }\n  return message\n}\n\n",
    "data": "import { state } from './state.js'\nimport { api } from './api.js'\nimport { toast } from './toast.js'\n\nexport async function loadAll(force) {\n  const suffix = force ? '?refresh=1' : ''\n  const values = await Promise.all([\n    api('/v1/admin/config'),\n    api('/v1/admin/api-keys'),\n    api('/v1/admin/overview' + suffix),\n    api('/v1/admin/runs?limit=200')\n  ])\n  state.config = values[0]\n  state.apiKeys = values[1].apiKeys || []\n  state.readiness = values[2].agents || []\n  state.sessions = values[2].sessions || 0\n  state.runs = values[3].runs || []\n  state.runTotal = values[3].total || 0\n}\n\nexport async function refreshRuns(showNotice) {\n  const { renderRuns } = await import('./render.js')\n  try {\n    const value = await api('/v1/admin/runs?limit=200')\n    state.runs = value.runs || []\n    state.runTotal = value.total || 0\n    if (state.page === 'runs') renderRuns()\n    if (showNotice) toast('运行记录已刷新')\n  } catch (error) {\n    if (showNotice) toast(error.message, true)\n  }\n}\n\nexport async function refreshReadiness(showNotice) {\n  const { render } = await import('./render.js')\n  try {\n    const overview = await api('/v1/admin/overview?refresh=1')\n    state.readiness = overview.agents || []\n    state.sessions = overview.sessions || 0\n    if (state.page === 'overview' || state.page === 'agents') render()\n    if (showNotice) toast('运行状态已刷新')\n  } catch (error) {\n    if (showNotice) toast(error.message, true)\n  }\n}\n\n",
    "dom": "export const byId = (id) => document.getElementById(id)\r\n\r\nexport const setupScreen = byId('setup-screen')\r\nexport const loginScreen = byId('login-screen')\r\nexport const appRoot = byId('app')\r\nexport const content = byId('page-content')\r\nexport const actions = byId('page-actions')\r\nexport const drawer = byId('drawer')\r\nexport const drawerBackdrop = byId('drawer-backdrop')\r\nexport const drawerForm = byId('drawer-form')\r\nexport const drawerFooter = byId('drawer-footer')\r\n\r\nexport const keyActionMenu = document.createElement('div')\r\nkeyActionMenu.className = 'key-action-menu hidden'\r\nkeyActionMenu.setAttribute('role', 'menu')\r\ndocument.body.appendChild(keyActionMenu)\r\n\r\nexport function escapeHtml(value) {\r\n  return String(value == null ? '' : value)\r\n    .replace(/&/g, '&amp;')\r\n    .replace(/</g, '&lt;')\r\n    .replace(/>/g, '&gt;')\r\n    .replace(/\"/g, '&quot;')\r\n    .replace(/'/g, '&#039;')\r\n}\r\n\r\nexport const selected = (value, expected) => (value === expected ? ' selected' : '')\r\nexport const checked = (value) => (value ? ' checked' : '')\r\n\r\n",
    "drawer": "import { byId, drawer, drawerBackdrop, drawerForm, drawerFooter, escapeHtml } from './dom.js'\r\nimport { runAction } from './toast.js'\r\n\r\nlet drawerSubmit = null\r\n\r\nexport function openDrawer(title, body, submitLabel, onSubmit, danger) {\r\n  byId('drawer-title').textContent = title\r\n  drawerForm.innerHTML = body + '<p class=\"form-error\" data-form-error></p>'\r\n  drawerFooter.innerHTML = '<button type=\"button\" class=\"button\" data-close-drawer>取消</button>' +\r\n    (submitLabel ? '<button type=\"submit\" form=\"drawer-form\" class=\"button ' + (danger ? 'solid-danger' : 'primary') + '\">' + escapeHtml(submitLabel) + '</button>' : '')\r\n  drawerSubmit = onSubmit || null\r\n  drawer.classList.remove('hidden')\r\n  drawerBackdrop.classList.remove('hidden')\r\n  const first = drawerForm.querySelector('input, select, textarea')\r\n  if (first) setTimeout(() => first.focus(), 0)\r\n}\r\n\r\nexport function closeDrawer() {\r\n  drawer.classList.add('hidden')\r\n  drawerBackdrop.classList.add('hidden')\r\n  drawerForm.innerHTML = ''\r\n  drawerFooter.innerHTML = ''\r\n  drawerSubmit = null\r\n}\r\n\r\nexport function openConfirmDrawer(title, message, confirmLabel, onConfirm) {\r\n  openDrawer(title, '<p class=\"confirm-text\">' + escapeHtml(message) + '</p>', confirmLabel, async () => {\r\n    closeDrawer()\r\n    await runAction(onConfirm)\r\n  }, true)\r\n  const cancel = drawerFooter.querySelector('[data-close-drawer]')\r\n  if (cancel) setTimeout(() => cancel.focus(), 0)\r\n}\r\n\r\nexport function getDrawerSubmit() {\r\n  return drawerSubmit\r\n}\r\n\r\n",
    "format": "export function shortId(value) {\n  return String(value || '').slice(0, 8)\n}\n\nexport function formatDate(timestamp) {\n  if (!timestamp) return '—'\n  return new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(timestamp))\n}\n\nexport function formatDuration(run) {\n  const ms = run.durationMs != null ? run.durationMs : Math.max(0, Date.now() - run.startedAt)\n  if (ms < 1000) return ms + ' 毫秒'\n  if (ms < 60_000) return Math.round(ms / 1000) + ' 秒'\n  if (ms < 3_600_000) return Math.floor(ms / 60_000) + ' 分 ' + Math.round(ms % 60_000 / 1000) + ' 秒'\n  return Math.floor(ms / 3_600_000) + ' 小时 ' + Math.round(ms % 3_600_000 / 60_000) + ' 分'\n}\n\nexport const runStateLabels = {\n  created: '已创建',\n  running: '运行中',\n  input_required: '等待输入',\n  permission_required: '等待授权',\n  completed: '已完成',\n  failed: '失败',\n  canceled: '已取消'\n}\n\nexport function runStatusLabel(value) {\n  return runStateLabels[value] || value\n}\n\nexport function permissionLabel(value) {\n  if (value === 'ask') return '询问'\n  if (value === 'allow') return '始终允许'\n  if (value === 'deny') return '拒绝'\n  return value || '—'\n}\n\n",
    "icons": "const svg = (inner) => '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\" focusable=\"false\">' + inner + '</svg>'\n\nexport const icons = {\n  search: svg('<circle cx=\"11\" cy=\"11\" r=\"7.5\"/><path d=\"m21 21-4.3-4.3\"/>'),\n  refresh: svg('<path d=\"M3 12a9 9 0 0 1 9-9 9.7 9.7 0 0 1 6.7 2.7L21 8\"/><path d=\"M21 3v5h-5\"/><path d=\"M21 12a9 9 0 0 1-9 9 9.7 9.7 0 0 1-6.7-2.7L3 16\"/><path d=\"M8 16H3v5\"/>'),\n  plus: svg('<path d=\"M5 12h14\"/><path d=\"M12 5v14\"/>'),\n  copy: svg('<rect x=\"9\" y=\"9\" width=\"10\" height=\"10\" rx=\"2\"/><path d=\"M15 9V7a2 2 0 0 0-2-2H7a2 2 0 0 0-2 2v6a2 2 0 0 0 2 2h2\"/>'),\n  disable: svg('<circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"m6.3 6.3 11.4 11.4\"/>'),\n  enable: svg('<circle cx=\"12\" cy=\"12\" r=\"8\"/><path d=\"m8.5 12 2.3 2.3 4.8-5\"/>'),\n  edit: svg('<path d=\"M12 20h8\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z\"/>'),\n  more: svg('<circle cx=\"5\" cy=\"12\" r=\"1\"/><circle cx=\"12\" cy=\"12\" r=\"1\"/><circle cx=\"19\" cy=\"12\" r=\"1\"/>'),\n  reveal: svg('<path d=\"M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z\"/><circle cx=\"12\" cy=\"12\" r=\"2.5\"/>'),\n  scope: svg('<path d=\"M12 3 5 6v5c0 4.7 2.9 8 7 10 4.1-2 7-5.3 7-10V6Z\"/><path d=\"M9.5 12 11 13.5l3.5-4\"/>'),\n  regenerate: svg('<path d=\"M20 7v5h-5\"/><path d=\"M19 12a7 7 0 1 0-2 5\"/>'),\n  trash: svg('<path d=\"M4 7h16\"/><path d=\"M9 7V4h6v3\"/><path d=\"m6 7 1 13h10l1-13\"/><path d=\"M10 11v5M14 11v5\"/>'),\n  folder: svg('<path d=\"M20 20a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-7.1a2 2 0 0 1-1.66-.89l-.75-1.12A2 2 0 0 0 8.83 4H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2Z\"/>'),\n  robot: svg('<path d=\"M12 8V4.5\"/><circle cx=\"12\" cy=\"3\" r=\"1.1\"/><rect x=\"4\" y=\"8\" width=\"16\" height=\"12\" rx=\"3\"/><path d=\"M2 14h2\"/><path d=\"M20 14h2\"/><path d=\"M9.5 13v1.6\"/><path d=\"M14.5 13v1.6\"/><path d=\"M9.5 17.2h5\"/>'),\n  activity: svg('<path d=\"M22 12h-2.5a2 2 0 0 0-1.93 1.46l-2.1 7.4a.25.25 0 0 1-.48 0L9.24 3.14a.25.25 0 0 0-.48 0l-2.1 7.4A2 2 0 0 1 4.73 12H2\"/>'),\n  key: svg('<circle cx=\"8\" cy=\"15\" r=\"4.2\"/><path d=\"m11.1 12 8-8\"/><path d=\"m15.4 7.7 2.9 2.9\"/><path d=\"m17.6 5.5 2.9 2.9\"/>')\n}\n\n",
    "main": "import { state } from './state.js'\r\nimport { byId, content, drawerForm, drawerFooter, drawerBackdrop, keyActionMenu } from './dom.js'\r\nimport { api } from './api.js'\r\nimport { toast, runAction } from './toast.js'\r\nimport { boot, enterApp, showLogin } from './screens.js'\r\nimport { applyTheme } from './theme.js'\r\nimport { loadAll, refreshRuns, refreshReadiness } from './data.js'\r\nimport { closeDrawer, getDrawerSubmit, openConfirmDrawer } from './drawer.js'\r\nimport {\r\n  render,\r\n  openRunDrawer,\r\n  openAgentDrawer,\r\n  openWorkspaceDrawer,\r\n  openPasswordDrawer,\r\n  openKeyDrawer,\r\n  openKeyScopeDrawer,\r\n  openRenameKeyDrawer,\r\n  showSecret,\r\n  copySecret,\r\n  reloadKeys,\r\n  toggleKeyActionMenu,\r\n  closeKeyActionMenu\r\n} from './render.js'\r\n\r\nfunction handleKeyAction(action, id) {\r\n  const key = state.apiKeys.find((item) => item.id === id)\r\n  if (!key) return\r\n  if (action === 'rename') {\r\n    openRenameKeyDrawer(key)\r\n    return\r\n  }\r\n  if (action === 'regenerate') {\r\n    openConfirmDrawer('重新生成 API 密钥', '当前密钥会立即失效，使用它的客户端必须改用新密钥。', '重新生成', async () => {\r\n      const value = await api('/v1/admin/api-keys/' + encodeURIComponent(id) + '/regenerate', { method: 'POST' })\r\n      await reloadKeys()\r\n      showSecret('API 密钥已重新生成', value.secret)\r\n    })\r\n    return\r\n  }\r\n  if (action === 'delete') {\r\n    openConfirmDrawer('删除 API 密钥', '使用该密钥的客户端会立即失去访问权限，此操作无法撤销。', '删除密钥', async () => {\r\n      await api('/v1/admin/api-keys/' + encodeURIComponent(id), { method: 'DELETE' })\r\n      await reloadKeys()\r\n      toast('API 密钥已删除')\r\n    })\r\n    return\r\n  }\r\n  void runAction(async () => {\r\n    if (action === 'copy') {\r\n      const value = await api('/v1/admin/api-keys/' + encodeURIComponent(id) + '/reveal', { method: 'POST' })\r\n      await copySecret(value.secret)\r\n      toast('API 密钥已复制')\r\n    }\r\n    if (action === 'reveal') {\r\n      const value = await api('/v1/admin/api-keys/' + encodeURIComponent(id) + '/reveal', { method: 'POST' })\r\n      showSecret('显示 API 密钥', value.secret)\r\n    }\r\n    if (action === 'scope') openKeyScopeDrawer(key)\r\n    if (action === 'toggle') {\r\n      await api('/v1/admin/api-keys/' + encodeURIComponent(id), { method: 'PATCH', body: { enabled: !key.enabled } })\r\n      await reloadKeys()\r\n      toast(key.enabled ? 'API 密钥已禁用' : 'API 密钥已启用')\r\n    }\r\n  })\r\n}\r\n\r\nasync function handleContentClick(event) {\r\n  const runTarget = event.target.closest('[data-run-detail]')\r\n  if (runTarget) {\r\n    await runAction(() => openRunDrawer(runTarget.dataset.runDetail))\r\n    return\r\n  }\r\n  const button = event.target.closest('button')\r\n  if (!button) return\r\n  if (button.dataset.emptyAction) {\r\n    if (button.dataset.emptyAction === 'add-agent') openAgentDrawer()\r\n    if (button.dataset.emptyAction === 'create-key') openKeyDrawer()\r\n    if (button.dataset.emptyAction === 'add-workspace') openWorkspaceDrawer()\r\n    return\r\n  }\r\n  if (button.dataset.keyMenu) {\r\n    toggleKeyActionMenu(button, button.dataset.keyMenu)\r\n    return\r\n  }\r\n  if (button.dataset.agentEdit) {\r\n    openAgentDrawer(state.config.agents.find((agent) => agent.id === button.dataset.agentEdit))\r\n    return\r\n  }\r\n  if (button.dataset.agentDelete) {\r\n    const id = button.dataset.agentDelete\r\n    openConfirmDrawer('删除智能体', '删除后该智能体不再接受新任务，已有会话不受影响。', '删除智能体', async () => {\r\n      state.config = await api('/v1/admin/agents/' + encodeURIComponent(id), { method: 'DELETE' })\r\n      await loadAll(true)\r\n      render()\r\n      toast('智能体已删除')\r\n    })\r\n    return\r\n  }\r\n  if (button.dataset.workspaceEdit !== undefined) {\r\n    openWorkspaceDrawer(Number(button.dataset.workspaceEdit))\r\n    return\r\n  }\r\n  if (button.dataset.workspaceDelete !== undefined) {\r\n    const index = Number(button.dataset.workspaceDelete)\r\n    const root = (state.config.workspaceRoots || [])[index] || ''\r\n    openConfirmDrawer('移除工作区', '移除后智能体将无法再访问 ' + root + '。', '移除根目录', async () => {\r\n      const roots = state.config.workspaceRoots.filter((_, itemIndex) => itemIndex !== index)\r\n      state.config = await api('/v1/admin/config/workspace-roots', { method: 'PUT', body: { workspaceRoots: roots } })\r\n      render()\r\n      toast('工作区已移除')\r\n    })\r\n    return\r\n  }\r\n  if (button.dataset.keyAction) handleKeyAction(button.dataset.keyAction, button.dataset.keyId)\r\n}\r\n\r\n/* ── Auth forms ───────────────────────────────────────────────────── */\r\n\r\nbyId('setup-form').onsubmit = async (event) => {\r\n  event.preventDefault()\r\n  const form = event.currentTarget\r\n  const error = form.querySelector('[data-form-error]')\r\n  error.textContent = ''\r\n  const data = new FormData(form)\r\n  try {\r\n    await api('/v1/bootstrap/initialize', { method: 'POST', body: { password: String(data.get('password') || ''), confirmPassword: String(data.get('confirmPassword') || '') } })\r\n    form.reset()\r\n    showLogin()\r\n    toast('初始化完成，请使用控制台密码登录。')\r\n  } catch (reason) { error.textContent = reason.message }\r\n}\r\n\r\nbyId('login-form').onsubmit = async (event) => {\r\n  event.preventDefault()\r\n  const form = event.currentTarget\r\n  const error = form.querySelector('[data-form-error]')\r\n  error.textContent = ''\r\n  try {\r\n    const data = new FormData(form)\r\n    await api('/v1/admin/auth/login', { method: 'POST', body: { password: String(data.get('password') || '') } })\r\n    form.reset()\r\n    await enterApp()\r\n  } catch (reason) { error.textContent = reason.message }\r\n}\r\n\r\n/* ── Navigation ───────────────────────────────────────────────────── */\r\n\r\ndocument.querySelectorAll('.nav-item').forEach((item) => {\r\n  item.onclick = () => {\r\n    state.page = item.dataset.page\r\n    render()\r\n    if (state.page === 'runs') void refreshRuns(false)\r\n  }\r\n})\r\n\r\n/* ── Global click delegation ──────────────────────────────────────── */\r\n\r\ncontent.addEventListener('click', (event) => { void handleContentClick(event) })\r\n\r\nkeyActionMenu.addEventListener('click', (event) => {\r\n  const button = event.target.closest('button[data-key-action]')\r\n  if (!button) return\r\n  closeKeyActionMenu()\r\n  void handleKeyAction(button.dataset.keyAction, button.dataset.keyId)\r\n})\r\n\r\n/* ── Drawer events ────────────────────────────────────────────────── */\r\n\r\ndrawerForm.onsubmit = async (event) => {\r\n  event.preventDefault()\r\n  const submit = getDrawerSubmit()\r\n  if (!submit) return\r\n  const error = drawerForm.querySelector('[data-form-error]')\r\n  error.textContent = ''\r\n  try { await submit(drawerForm) } catch (reason) { error.textContent = reason.message }\r\n}\r\ndrawerForm.addEventListener('click', (event) => {\r\n  if (event.target.closest('[data-close-drawer]')) closeDrawer()\r\n})\r\ndrawerFooter.addEventListener('click', (event) => {\r\n  if (event.target.closest('[data-close-drawer]')) closeDrawer()\r\n})\r\nbyId('drawer-close').onclick = closeDrawer\r\ndrawerBackdrop.onclick = closeDrawer\r\n\r\n/* ── Admin menu ───────────────────────────────────────────────────── */\r\n\r\nbyId('admin-menu').onclick = () => {\r\n  const popover = byId('admin-popover')\r\n  const hidden = popover.classList.toggle('hidden')\r\n  byId('admin-menu').setAttribute('aria-expanded', String(!hidden))\r\n}\r\nbyId('theme-select').onchange = (event) => {\r\n  localStorage.setItem('agent-nexus-theme', event.target.value)\r\n  applyTheme(event.target.value)\r\n}\r\nbyId('change-password').onclick = () => { byId('admin-popover').classList.add('hidden'); openPasswordDrawer() }\r\nbyId('logout').onclick = async () => {\r\n  await runAction(async () => {\r\n    await api('/v1/admin/auth/logout', { method: 'POST' })\r\n    showLogin()\r\n  })\r\n}\r\n\r\n/* ── Global listeners ─────────────────────────────────────────────── */\r\n\r\ndocument.addEventListener('click', (event) => {\r\n  if (!event.target.closest('.admin-menu-wrap')) byId('admin-popover').classList.add('hidden')\r\n  if (!event.target.closest('.key-action-menu') && !event.target.closest('[data-key-menu]')) closeKeyActionMenu()\r\n})\r\nmatchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {\r\n  if ((localStorage.getItem('agent-nexus-theme') || 'system') === 'system') applyTheme('system')\r\n})\r\ndocument.addEventListener('keydown', (event) => {\r\n  if (event.key === 'Escape') {\r\n    closeKeyActionMenu()\r\n    closeDrawer()\r\n  }\r\n})\r\nwindow.addEventListener('resize', closeKeyActionMenu)\r\nwindow.addEventListener('scroll', closeKeyActionMenu, true)\r\n\r\n/* ── Pollers ──────────────────────────────────────────────────────── */\r\n\r\nsetInterval(() => {\r\n  if (state.authenticated) void refreshReadiness(false)\r\n}, 20_000)\r\n\r\nsetInterval(() => {\r\n  if (state.authenticated && state.page === 'runs') void refreshRuns(false)\r\n}, 5_000)\r\n\r\nvoid boot()\r\n\r\n",
    "render": "import { state, pageMeta } from './state.js'\r\nimport { byId, content, actions, keyActionMenu, escapeHtml, selected, checked } from './dom.js'\r\nimport { icons } from './icons.js'\r\nimport { api, localizeError } from './api.js'\r\nimport { toast, runAction } from './toast.js'\r\nimport { openDrawer, closeDrawer } from './drawer.js'\r\nimport { showLogin } from './screens.js'\r\nimport { loadAll, refreshRuns, refreshReadiness } from './data.js'\r\nimport { shortId, formatDate, formatDuration, runStatusLabel, permissionLabel } from './format.js'\r\n\r\nexport function render() {\r\n  byId('page-title').textContent = pageMeta[state.page]\r\n  document.querySelectorAll('.nav-item').forEach((item) => {\r\n    item.classList.toggle('active', item.dataset.page === state.page)\r\n  })\r\n  if (state.page === 'overview') renderOverview()\r\n  if (state.page === 'runs') renderRuns()\r\n  if (state.page === 'agents') renderAgents()\r\n  if (state.page === 'workspaces') renderWorkspaces()\r\n  if (state.page === 'keys') renderApiKeys()\r\n  if (state.page === 'settings') renderSettings()\r\n}\r\n\r\n/* ── Overview ─────────────────────────────────────────────────────── */\r\n\r\nfunction stat(label, value) {\r\n  return '<div class=\"stat\"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(value) + '</strong></div>'\r\n}\r\n\r\nfunction statusMarkup(agent) {\r\n  if (!agent.enabled) return '<span class=\"status\">已禁用</span>'\r\n  if (agent.checking) return '<span class=\"status checking\">检查中</span>'\r\n  return agent.ready ? '<span class=\"status ready\">就绪</span>' : '<span class=\"status failed\">不可用</span>'\r\n}\r\n\r\nexport function readinessRows() {\r\n  const readiness = new Map(state.readiness.map((agent) => [agent.id, agent]))\r\n  return state.config.agents.map((agent) => readiness.get(agent.id) || {\r\n    id: agent.id,\r\n    name: agent.name,\r\n    protocol: agent.protocol,\r\n    driver: agent.driver,\r\n    enabled: agent.enabled,\r\n    ready: false,\r\n    checking: true\r\n  })\r\n}\r\n\r\nfunction overviewAgent(agent) {\r\n  return '<div class=\"list-row\"><div class=\"list-row-main\"><strong>' + escapeHtml(agent.name) + '</strong><small>' +\r\n    escapeHtml(agent.protocol.toUpperCase() + (agent.driver ? ' · ' + agent.driver : '')) +\r\n    (agent.error ? ' · ' + escapeHtml(localizeError(agent.error)) : '') + '</small></div>' + statusMarkup(agent) + '</div>'\r\n}\r\n\r\nfunction renderOverview() {\r\n  const agents = readinessRows()\r\n  const ready = agents.filter((agent) => agent.ready).length\r\n  actions.innerHTML = '<button id=\"refresh-overview\" class=\"button\">' + icons.refresh + '刷新</button>'\r\n  content.innerHTML =\r\n    '<div class=\"stats\">' +\r\n      stat('智能体', agents.length) +\r\n      stat('就绪', ready) +\r\n      stat('会话', state.sessions) +\r\n    '</div>' +\r\n    '<div class=\"panel\"><div class=\"panel-header\"><h2>智能体</h2></div>' +\r\n      (agents.length\r\n        ? '<div class=\"panel-body overview-list\">' + agents.map(overviewAgent).join('') + '</div>'\r\n        : emptyState(icons.robot, '尚未配置智能体', '', { action: 'add-agent', label: '添加智能体' })) +\r\n    '</div>'\r\n  byId('refresh-overview').onclick = () => refreshReadiness(true)\r\n}\r\n\r\n/* ── Runs ─────────────────────────────────────────────────────────── */\r\n\r\nfunction runSummary(label, value) {\r\n  return '<div class=\"stat\"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(value) + '</strong></div>'\r\n}\r\n\r\nfunction runStatus(value) {\r\n  const style = value === 'completed' ? ' completed' : value === 'failed' ? ' failed' : value === 'running' ? ' running' : (value === 'input_required' || value === 'permission_required') ? ' waiting' : ' canceled'\r\n  return '<span class=\"status' + style + '\">' + escapeHtml(runStatusLabel(value)) + '</span>'\r\n}\r\n\r\nfunction runCard(run) {\r\n  const waiting = run.state === 'input_required' || run.state === 'permission_required'\r\n  return '<article class=\"run-card' + (waiting ? ' waiting' : '') + '\" data-run-detail=\"' + escapeHtml(run.id) + '\" tabindex=\"0\"><div class=\"run-card-head\"><div class=\"run-card-agent\"><span class=\"badge\">' + escapeHtml(run.protocol.toUpperCase()) + '</span><strong>' + escapeHtml(run.agentName) + '</strong></div>' + runStatus(run.state) + '</div><div class=\"run-task\">' + escapeHtml(run.task) + '</div><div class=\"run-progress\"><strong>' + escapeHtml(run.progress && run.progress.phase || '运行中') + '</strong><small>' + escapeHtml(run.progress && run.progress.message || '等待最新进度') + '</small></div><div class=\"run-meta\"><span>' + escapeHtml(shortId(run.id)) + '</span><span>' + escapeHtml(formatDuration(run)) + '</span></div></article>'\r\n}\r\n\r\nfunction runRow(run) {\r\n  return '<tr data-run-detail=\"' + escapeHtml(run.id) + '\"><td><div class=\"agent-name\"><strong>' + escapeHtml(run.agentName) + '</strong><small>' + escapeHtml(run.protocol.toUpperCase()) + '</small></div></td><td class=\"run-task-cell\"><strong>' + escapeHtml(run.task) + '</strong><small class=\"run-id\">' + escapeHtml(shortId(run.id)) + '</small></td><td class=\"run-task-cell\"><strong>' + escapeHtml(run.resultSummary || run.error || '—') + '</strong><small>' + escapeHtml(run.progress && run.progress.phase || '') + '</small></td><td>' + runStatus(run.state) + '</td><td class=\"num\">' + escapeHtml(formatDate(run.startedAt)) + '</td><td class=\"num\">' + escapeHtml(formatDuration(run)) + '</td></tr>'\r\n}\r\n\r\nexport function renderRuns() {\r\n  const activeStates = new Set(['running', 'input_required', 'permission_required'])\r\n  const filtered = state.runs.filter((run) => {\r\n    const haystack = (run.task + ' ' + run.agentName + ' ' + run.id).toLowerCase()\r\n    return haystack.indexOf(state.runSearch.toLowerCase()) >= 0 &&\r\n      (state.runAgent === 'all' || run.agentId === state.runAgent) &&\r\n      (state.runStatus === 'all' || run.state === state.runStatus)\r\n  })\r\n  const active = filtered.filter((run) => activeStates.has(run.state))\r\n  const history = filtered.filter((run) => !activeStates.has(run.state))\r\n  const completed = state.runs.filter((run) => run.state === 'completed').length\r\n  const failed = state.runs.filter((run) => run.state === 'failed').length\r\n  const agentOptions = state.config.agents.map((agent) => '<option value=\"' + escapeHtml(agent.id) + '\"' + selected(state.runAgent, agent.id) + '>' + escapeHtml(agent.name) + '</option>').join('')\r\n  actions.innerHTML = '<button id=\"refresh-runs\" class=\"button\">' + icons.refresh + '刷新</button>'\r\n  byId('refresh-runs').onclick = () => refreshRuns(true)\r\n\r\n  if (!state.runs.length) {\r\n    content.innerHTML = '<div class=\"panel\">' +\r\n      emptyState(icons.activity, '暂无运行记录', '客户端通过网关数据接口发起任务后，进度与结果会出现在这里。') +\r\n      '</div>'\r\n    return\r\n  }\r\n\r\n  content.innerHTML =\r\n    '<div class=\"run-summary\">' +\r\n      runSummary('当前运行', state.runs.filter((run) => activeStates.has(run.state)).length) +\r\n      runSummary('已完成', completed) +\r\n      runSummary('失败', failed) +\r\n      runSummary('保留记录', state.runTotal) +\r\n    '</div>' +\r\n    '<div class=\"toolbar\"><div class=\"search-box\">' + icons.search + '<input id=\"run-search\" type=\"search\" placeholder=\"搜索任务、智能体或运行 ID\" value=\"' + escapeHtml(state.runSearch) + '\"></div>' +\r\n    '<select id=\"run-agent-filter\"><option value=\"all\">全部智能体</option>' + agentOptions + '</select>' +\r\n    '<select id=\"run-status-filter\"><option value=\"all\">全部状态</option><option value=\"running\"' + selected(state.runStatus, 'running') + '>运行中</option><option value=\"input_required\"' + selected(state.runStatus, 'input_required') + '>等待输入</option><option value=\"permission_required\"' + selected(state.runStatus, 'permission_required') + '>等待授权</option><option value=\"completed\"' + selected(state.runStatus, 'completed') + '>已完成</option><option value=\"failed\"' + selected(state.runStatus, 'failed') + '>失败</option><option value=\"canceled\"' + selected(state.runStatus, 'canceled') + '>已取消</option></select></div>' +\r\n    '<section class=\"run-section\"><div class=\"run-section-title\"><h2>当前运行</h2><span>' + active.length + ' 项</span></div>' +\r\n      (active.length ? '<div class=\"run-live-grid\">' + active.map(runCard).join('') + '</div>' : '<div class=\"panel\">' + emptyState(icons.activity, '当前没有任务') + '</div>') +\r\n    '</section>' +\r\n    '<section class=\"run-section\"><div class=\"run-section-title\"><h2>历史记录</h2><span>' + history.length + ' 项</span></div>' +\r\n      '<div class=\"table-wrap\"><table class=\"run-table\"><thead><tr><th>智能体</th><th>任务</th><th>结果</th><th>状态</th><th class=\"num\">开始时间</th><th class=\"num\">耗时</th></tr></thead><tbody>' +\r\n      (history.length ? history.map(runRow).join('') : '<tr><td colspan=\"6\" class=\"empty\">没有符合条件的历史记录。</td></tr>') +\r\n      '</tbody></table></div></section>'\r\n  bindSearch('run-search', (value) => { state.runSearch = value; renderRuns() })\r\n  byId('run-agent-filter').onchange = (event) => { state.runAgent = event.target.value; renderRuns() }\r\n  byId('run-status-filter').onchange = (event) => { state.runStatus = event.target.value; renderRuns() }\r\n}\r\n\r\nfunction detailItem(label, value) {\r\n  return '<div class=\"run-detail-item\"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(value) + '</strong></div>'\r\n}\r\n\r\nexport async function openRunDrawer(id) {\r\n  const run = await api('/v1/admin/runs/' + encodeURIComponent(id))\r\n  const artifacts = run.artifacts && run.artifacts.length\r\n    ? '<div class=\"run-detail-block\"><h3>产物</h3><div class=\"overview-list\">' + run.artifacts.map((artifact) => '<div class=\"list-row\"><div class=\"list-row-main\"><strong>' + escapeHtml(artifact.name || artifact.filename || artifact.id || '未命名产物') + '</strong><small>' + escapeHtml(artifact.mediaType || artifact.url || '') + '</small></div></div>').join('') + '</div></div>'\r\n    : ''\r\n  const body = '<div class=\"run-detail-grid\">' +\r\n    detailItem('智能体', run.agentName) + detailItem('状态', runStatusLabel(run.state)) +\r\n    detailItem('开始时间', formatDate(run.startedAt)) + detailItem('耗时', formatDuration(run)) +\r\n    detailItem('协议', run.protocol.toUpperCase()) + detailItem('运行 ID', run.id) +\r\n    detailItem('当前阶段', run.progress && run.progress.phase || '—') + detailItem('输入附件', run.inputAttachmentCount || 0) + detailItem('产物', run.artifactCount || 0) +\r\n    '</div><div class=\"run-detail-block\"><h3>用户任务</h3><pre class=\"run-detail-code\">' + escapeHtml(run.task) + (run.taskTruncated ? '\\n\\n[记录已截断]' : '') + '</pre></div>' +\r\n    (run.progress && run.progress.message ? '<div class=\"run-detail-block\"><h3>最近进度</h3><pre class=\"run-detail-code\">' + escapeHtml(run.progress.message) + '</pre></div>' : '') +\r\n    (run.output ? '<div class=\"run-detail-block\"><h3>智能体结果</h3><pre class=\"run-detail-code\">' + escapeHtml(run.output) + '</pre></div>' : '') +\r\n    (run.error ? '<div class=\"run-detail-block\"><h3>错误</h3><pre class=\"run-detail-code\">' + escapeHtml(run.error) + '</pre></div>' : '') + artifacts\r\n  openDrawer('运行详情 · ' + run.agentName, body, '', null)\r\n}\r\n\r\n/* ── Agents ───────────────────────────────────────────────────────── */\r\n\r\nfunction agentRow(agent, live) {\r\n  const statusAgent = live || { ready: false, enabled: agent.enabled, checking: true }\r\n  return '<tr><td><div class=\"agent-name\"><strong>' + escapeHtml(agent.name) + '</strong><small>' + escapeHtml(agent.id) + '</small>' +\r\n    (statusAgent.error && agent.enabled ? '<span class=\"error-detail\">' + escapeHtml(localizeError(statusAgent.error)) + '</span>' : '') +\r\n    '</div></td><td><span class=\"badge\">' + escapeHtml(agent.protocol.toUpperCase()) + '</span></td><td>' + escapeHtml(agent.driver || '—') + '</td><td>' + statusMarkup(statusAgent) + '</td><td>' + escapeHtml(agent.workspace || '—') + '</td><td>' + escapeHtml(permissionLabel(agent.permissionPolicy)) + '</td><td><div class=\"row-actions\"><button class=\"button small\" data-agent-edit=\"' + escapeHtml(agent.id) + '\">编辑</button><button class=\"button small danger\" data-agent-delete=\"' + escapeHtml(agent.id) + '\">删除</button></div></td></tr>'\r\n}\r\n\r\nfunction renderAgents() {\r\n  actions.innerHTML = '<button id=\"refresh-agents\" class=\"button\">' + icons.refresh + '刷新</button><button id=\"add-agent\" class=\"button primary\">' + icons.plus + '添加智能体</button>'\r\n  byId('refresh-agents').onclick = () => refreshReadiness(true)\r\n  byId('add-agent').onclick = () => openAgentDrawer()\r\n\r\n  if (!state.config.agents.length) {\r\n    content.innerHTML = '<div class=\"panel\">' +\r\n      emptyState(icons.robot, '尚未配置智能体', '智能体是网关转发任务的执行端，支持本地 ACP 进程与远程 A2A 服务。', { action: 'add-agent', label: '添加智能体' }) +\r\n      '</div>'\r\n    return\r\n  }\r\n\r\n  const readiness = new Map(state.readiness.map((agent) => [agent.id, agent]))\r\n  const rows = state.config.agents.filter((agent) => {\r\n    const live = readiness.get(agent.id) || {}\r\n    const haystack = (agent.name + ' ' + agent.id + ' ' + (agent.description || '')).toLowerCase()\r\n    const status = !readiness.has(agent.id) ? 'checking' : live.ready ? 'ready' : agent.enabled ? 'failed' : 'disabled'\r\n    return haystack.indexOf(state.search.toLowerCase()) >= 0 &&\r\n      (state.protocol === 'all' || agent.protocol === state.protocol) &&\r\n      (state.status === 'all' || status === state.status)\r\n  })\r\n  content.innerHTML =\r\n    '<div class=\"toolbar\"><div class=\"search-box\">' + icons.search + '<input id=\"agent-search\" type=\"search\" placeholder=\"搜索智能体\" value=\"' + escapeHtml(state.search) + '\"></div>' +\r\n    '<select id=\"protocol-filter\"><option value=\"all\">全部协议</option><option value=\"acp\"' + selected(state.protocol, 'acp') + '>ACP</option><option value=\"a2a\"' + selected(state.protocol, 'a2a') + '>A2A</option></select>' +\r\n    '<select id=\"status-filter\"><option value=\"all\">全部状态</option><option value=\"ready\"' + selected(state.status, 'ready') + '>就绪</option><option value=\"failed\"' + selected(state.status, 'failed') + '>不可用</option><option value=\"disabled\"' + selected(state.status, 'disabled') + '>已禁用</option></select></div>' +\r\n    '<div class=\"table-wrap\"><table><thead><tr><th>智能体</th><th>协议</th><th>驱动</th><th>状态</th><th>工作区</th><th>权限策略</th><th></th></tr></thead><tbody>' +\r\n    (rows.length ? rows.map((agent) => agentRow(agent, readiness.get(agent.id))).join('') : '<tr><td colspan=\"7\" class=\"empty\">没有符合条件的智能体。</td></tr>') +\r\n    '</tbody></table></div>'\r\n  bindSearch('agent-search', (value) => { state.search = value; renderAgents() })\r\n  byId('protocol-filter').onchange = (event) => { state.protocol = event.target.value; renderAgents() }\r\n  byId('status-filter').onchange = (event) => { state.status = event.target.value; renderAgents() }\r\n}\r\n\r\n/* ── Workspaces ───────────────────────────────────────────────────── */\r\n\r\nfunction workspaceRow(root, index, total) {\r\n  const usedBy = state.config.agents.filter((agent) => agent.workspace === root).map((agent) => escapeHtml(agent.name))\r\n  return '<div class=\"list-row\"><div class=\"list-row-main\"><strong class=\"path\">' + escapeHtml(root) + '</strong>' +\r\n    '<small>' + (usedBy.length ? '使用中：' + usedBy.join('、') : '没有智能体使用') + '</small></div>' +\r\n    '<div class=\"row-actions\"><button class=\"button small\" data-workspace-edit=\"' + index + '\">编辑</button>' +\r\n    '<button class=\"button small danger\" data-workspace-delete=\"' + index + '\"' +\r\n    (total === 1 ? ' disabled title=\"至少保留一个根目录\"' : '') + '>删除</button></div></div>'\r\n}\r\n\r\nfunction renderWorkspaces() {\r\n  actions.innerHTML = '<button id=\"add-workspace\" class=\"button primary\">' + icons.plus + '添加工作区</button>'\r\n  byId('add-workspace').onclick = () => openWorkspaceDrawer()\r\n  const roots = state.config.workspaceRoots || []\r\n  content.innerHTML = '<div class=\"panel\"><div class=\"panel-header\"><h2>允许的根目录</h2><span class=\"muted\">' + roots.length + ' 个</span></div>' +\r\n    (roots.length\r\n      ? '<div class=\"panel-body workspace-list\">' + roots.map((root, index) => workspaceRow(root, index, roots.length)).join('') + '</div>'\r\n      : emptyState(icons.folder, '尚未配置工作区', '', { action: 'add-workspace', label: '添加工作区' })) +\r\n    '</div>'\r\n}\r\n\r\n/* ── API keys ─────────────────────────────────────────────────────── */\r\n\r\nfunction keyRow(key) {\r\n  const scope = key.scope.allAgents ? '全部智能体' : (key.scope.agentIds.length ? key.scope.agentIds.join(', ') : '未授权智能体')\r\n  const name = key.legacy && key.name === 'Legacy Access Key' ? '旧版访问密钥' : key.name\r\n  const id = escapeHtml(key.id)\r\n  const toggleLabel = key.enabled ? '禁用密钥' : '启用密钥'\r\n  return '<tr><td><div class=\"agent-name\"><strong>' + escapeHtml(name) + '</strong></div></td>' +\r\n    '<td>' + (key.enabled ? '<span class=\"status ready\">已启用</span>' : '<span class=\"status\">已禁用</span>') + '</td>' +\r\n    '<td><div class=\"key-secret-cell\"><code>••••' + escapeHtml(key.suffix) + '</code><button class=\"key-copy-button\" data-key-action=\"copy\" data-key-id=\"' + id + '\" aria-label=\"复制完整密钥\" title=\"复制完整密钥\">' + icons.copy + '</button></div></td>' +\r\n    '<td><span class=\"key-scope\">' + escapeHtml(scope) + '</span></td>' +\r\n    '<td><span class=\"key-last-used\">' + escapeHtml(key.lastUsedAt ? formatDate(key.lastUsedAt) : '从未使用') + '</span></td>' +\r\n    '<td><div class=\"key-actions\"><button class=\"key-icon-button' + (key.enabled ? ' danger-action' : '') + '\" data-key-action=\"toggle\" data-key-id=\"' + id + '\" aria-label=\"' + toggleLabel + '\" title=\"' + toggleLabel + '\">' + (key.enabled ? icons.disable : icons.enable) + '</button><button class=\"key-icon-button\" data-key-action=\"rename\" data-key-id=\"' + id + '\" aria-label=\"重命名\" title=\"重命名\">' + icons.edit + '</button><button class=\"key-icon-button\" data-key-menu=\"' + id + '\" aria-label=\"更多操作\" title=\"更多操作\" aria-expanded=\"false\">' + icons.more + '</button></div></td></tr>'\r\n}\r\n\r\nfunction renderApiKeys() {\r\n  closeKeyActionMenu()\r\n  actions.innerHTML = '<button id=\"create-key\" class=\"button primary\">' + icons.plus + '创建 API 密钥</button>'\r\n  content.innerHTML = state.apiKeys.length\r\n    ? '<div class=\"table-wrap key-table-wrap\"><table class=\"key-table\"><thead><tr><th>名称</th><th>状态</th><th>API 密钥</th><th>授权范围</th><th>最后使用</th><th>操作</th></tr></thead><tbody>' + state.apiKeys.map(keyRow).join('') + '</tbody></table></div>'\r\n    : '<div class=\"panel\">' + emptyState(icons.key, '尚未创建 API 密钥', '客户端调用网关数据接口时需要携带密钥。', { action: 'create-key', label: '创建 API 密钥' }) + '</div>'\r\n  byId('create-key').onclick = () => openKeyDrawer()\r\n}\r\n\r\nfunction emptyState(icon, title, text, cta) {\r\n  return '<div class=\"empty-state\">' + icon + '<strong>' + escapeHtml(title) + '</strong>' +\r\n    (text ? '<span>' + escapeHtml(text) + '</span>' : '') +\r\n    (cta ? '<button type=\"button\" class=\"button primary\" data-empty-action=\"' + escapeHtml(cta.action) + '\">' + icons.plus + escapeHtml(cta.label) + '</button>' : '') +\r\n    '</div>'\r\n}\r\n\r\n/* 重渲染会销毁输入框，必须把焦点和光标还给新建的那个，否则每敲一个字就失焦 */\r\nfunction bindSearch(id, apply) {\r\n  byId(id).oninput = (event) => {\r\n    const caret = event.target.selectionStart\r\n    apply(event.target.value)\r\n    const next = byId(id)\r\n    next.focus()\r\n    next.setSelectionRange(caret, caret)\r\n  }\r\n}\r\n\r\n/* ── Settings ─────────────────────────────────────────────────────── */\r\n\r\nfunction renderSettings() {\r\n  const sessionTtlHours = Math.round((state.config.sessionTtlMs || 24 * 60 * 60 * 1000) / 3_600_000)\r\n  const promptTimeoutMinutes = Math.round((state.config.promptTimeoutMs || 30 * 60 * 1000) / 60_000)\r\n  const cleanupIntervalSeconds = Math.round((state.config.cleanupIntervalMs || 60_000) / 1000)\r\n  actions.innerHTML = ''\r\n  content.innerHTML =\r\n    '<div class=\"settings-layout\"><section class=\"panel settings-form\"><div class=\"panel-header\"><h2>运行生命周期</h2></div>' +\r\n    '<div class=\"settings-fields\">' +\r\n    '<div class=\"field\"><label for=\"session-ttl-hours\">Session 空闲有效期（小时）</label><input id=\"session-ttl-hours\" type=\"number\" min=\"1\" max=\"720\" step=\"1\" value=\"' + escapeHtml(sessionTtlHours) + '\"><small class=\"field-help\">无活动超过该时长后释放 Session。默认 24 小时。</small></div>' +\r\n    '<div class=\"field\"><label for=\"prompt-timeout-minutes\">单次 ACP 任务超时（分钟）</label><input id=\"prompt-timeout-minutes\" type=\"number\" min=\"1\" max=\"1440\" step=\"1\" value=\"' + escapeHtml(promptTimeoutMinutes) + '\"><small class=\"field-help\">超时后任务记为失败并释放资源。默认 30 分钟。</small></div>' +\r\n    '<div class=\"field\"><label for=\"cleanup-interval-seconds\">清理任务周期（秒）</label><input id=\"cleanup-interval-seconds\" type=\"number\" min=\"5\" max=\"3600\" step=\"1\" value=\"' + escapeHtml(cleanupIntervalSeconds) + '\"><small class=\"field-help\">扫描空闲 Session 与过期记录的间隔。默认 60 秒。</small></div>' +\r\n    '</div><div class=\"settings-actions\"><button id=\"save-runtime-settings\" class=\"button primary\">保存运行设置</button></div></section></div>'\r\n  byId('save-runtime-settings').onclick = async () => {\r\n    const values = {\r\n      sessionTtlMs: Number(byId('session-ttl-hours').value) * 3_600_000,\r\n      promptTimeoutMs: Number(byId('prompt-timeout-minutes').value) * 60_000,\r\n      cleanupIntervalMs: Number(byId('cleanup-interval-seconds').value) * 1000\r\n    }\r\n    if (!Object.values(values).every((value) => Number.isInteger(value) && value > 0)) {\r\n      toast('请输入有效的整数运行参数。', true)\r\n      return\r\n    }\r\n    await runAction(async () => {\r\n      state.config = await api('/v1/admin/config/runtime', { method: 'PUT', body: values })\r\n      render()\r\n      toast('运行设置已保存并立即生效')\r\n    })\r\n  }\r\n}\r\n\r\n/* ── Drawers: agent / workspace / key / password ──────────────────── */\r\n\r\nexport function openAgentDrawer(agent) {\r\n  const editing = Boolean(agent)\r\n  const current = agent || { protocol: 'acp', enabled: true, permissionPolicy: 'ask', permissionTimeoutMs: 900000, timeoutMs: 60000 }\r\n  const permissionTimeoutSeconds = Math.max(1, Math.round(Number(current.permissionTimeoutMs || 900000) / 1000))\r\n  const requestTimeoutSeconds = Math.max(1, Math.round(Number(current.timeoutMs || 60000) / 1000))\r\n  const drivers = state.config.driverKinds.map((driver) => '<option value=\"' + escapeHtml(driver) + '\"' + selected(current.driver || state.config.driverKinds[0], driver) + '>' + escapeHtml(driver) + '</option>').join('')\r\n  const roots = state.config.workspaceRoots.map((root) => '<option value=\"' + escapeHtml(root) + '\"></option>').join('')\r\n  const body =\r\n    '<div class=\"field\"><label for=\"f-id\">智能体 ID</label><input id=\"f-id\" name=\"id\" value=\"' + escapeHtml(current.id || '') + '\" pattern=\"[a-z0-9][a-z0-9._\\\\-]{0,63}\" required' + (editing ? ' disabled' : '') + '></div>' +\r\n    '<div class=\"field-row\"><div class=\"field\"><label for=\"f-protocol\">协议</label><select id=\"f-protocol\" name=\"protocol\"><option value=\"acp\"' + selected(current.protocol, 'acp') + '>ACP</option><option value=\"a2a\"' + selected(current.protocol, 'a2a') + '>A2A</option></select></div><div class=\"field\"><label>&nbsp;</label><label class=\"checkbox\"><input name=\"enabled\" type=\"checkbox\"' + checked(current.enabled) + '>启用</label></div></div>' +\r\n    '<div class=\"field\"><label for=\"f-name\">名称</label><input id=\"f-name\" name=\"name\" value=\"' + escapeHtml(current.name || '') + '\" required></div>' +\r\n    '<div class=\"field\"><label for=\"f-description\">描述</label><textarea id=\"f-description\" name=\"description\">' + escapeHtml(current.description || '') + '</textarea></div>' +\r\n    '<div data-protocol-section=\"acp\"><div class=\"field\"><label for=\"f-driver\">驱动</label><select id=\"f-driver\" name=\"driver\">' + drivers + '</select></div><div class=\"field\"><label for=\"f-workspace\">工作区</label><input id=\"f-workspace\" name=\"workspace\" list=\"workspace-roots\" value=\"' + escapeHtml(current.workspace || state.config.workspaceRoots[0] || '') + '\" required><datalist id=\"workspace-roots\">' + roots + '</datalist></div><div class=\"field-row\"><div class=\"field\"><label for=\"f-permissionPolicy\">权限策略</label><select id=\"f-permissionPolicy\" name=\"permissionPolicy\"><option value=\"ask\"' + selected(current.permissionPolicy, 'ask') + '>询问</option><option value=\"allow\"' + selected(current.permissionPolicy, 'allow') + '>始终允许</option><option value=\"deny\"' + selected(current.permissionPolicy, 'deny') + '>拒绝</option></select></div><div class=\"field\"><label for=\"f-permissionTimeoutMs\">权限确认超时（秒）</label><input id=\"f-permissionTimeoutMs\" name=\"permissionTimeoutMs\" type=\"number\" min=\"1\" max=\"86400\" step=\"1\" value=\"' + escapeHtml(permissionTimeoutSeconds) + '\"><small class=\"field-help\">默认 900 秒，最长 24 小时；选择「始终允许」时不生效。</small></div></div></div>' +\r\n    '<div data-protocol-section=\"a2a\"><div class=\"field\"><label for=\"f-agentCardUrl\">Agent Card URL</label><input id=\"f-agentCardUrl\" name=\"agentCardUrl\" type=\"url\" value=\"' + escapeHtml(current.agentCardUrl || '') + '\" placeholder=\"http://agent.local:8080/.well-known/agent-card.json\" required><small class=\"field-help\">调用地址与能力从 Card 自动发现。</small></div><div class=\"field-row\"><div class=\"field\"><label for=\"f-preferredTransport\">首选传输</label><select id=\"f-preferredTransport\" name=\"preferredTransport\"><option value=\"auto\"' + selected(current.preferredTransport || 'auto', 'auto') + '>自动（按 Card）</option><option value=\"jsonrpc\"' + selected(current.preferredTransport, 'jsonrpc') + '>JSON-RPC</option><option value=\"http-json\"' + selected(current.preferredTransport, 'http-json') + '>HTTP+JSON</option></select></div><div class=\"field\"><label for=\"f-authType\">认证方式</label><select id=\"f-authType\" name=\"authType\"><option value=\"none\"' + selected(current.auth && current.auth.type || 'none', 'none') + '>无认证</option><option value=\"bearer\"' + selected(current.auth && current.auth.type, 'bearer') + '>Bearer Token</option><option value=\"header\"' + selected(current.auth && current.auth.type, 'header') + '>自定义请求头</option></select></div></div><div class=\"field\" data-auth-header><label for=\"f-authHeaderName\">请求头名称</label><input id=\"f-authHeaderName\" name=\"authHeaderName\" value=\"' + escapeHtml(current.auth && current.auth.headerName || '') + '\" placeholder=\"X-API-Key\"></div><div class=\"field\" data-auth-value><label data-auth-value-label for=\"f-authValue\">认证凭据</label><input id=\"f-authValue\" name=\"authValue\" type=\"password\" autocomplete=\"off\" placeholder=\"' + (editing && current.auth && current.auth.configured ? '留空以保留当前凭据' : '') + '\"></div><div class=\"field\"><label for=\"f-timeoutMs\">请求超时（秒）</label><input id=\"f-timeoutMs\" name=\"timeoutMs\" type=\"number\" min=\"1\" max=\"1800\" step=\"1\" value=\"' + escapeHtml(requestTimeoutSeconds) + '\"><small class=\"field-help\">单次请求上限。默认 60 秒，最大 1800 秒。</small></div></div>'\r\n  openDrawer(editing ? '编辑智能体' : '添加智能体', body, editing ? '保存修改' : '添加智能体', async (form) => {\r\n    const data = new FormData(form)\r\n    const protocol = data.get('protocol')\r\n    const id = editing ? current.id : String(data.get('id') || '').trim().toLowerCase()\r\n    const payload = {\r\n      protocol,\r\n      name: String(data.get('name') || '').trim(),\r\n      description: String(data.get('description') || '').trim(),\r\n      enabled: data.get('enabled') === 'on'\r\n    }\r\n    if (protocol === 'acp') {\r\n      payload.driver = data.get('driver')\r\n      payload.workspace = String(data.get('workspace') || '').trim()\r\n      payload.permissionPolicy = data.get('permissionPolicy')\r\n      payload.permissionTimeoutMs = Number(data.get('permissionTimeoutMs')) * 1000\r\n    } else {\r\n      payload.agentCardUrl = String(data.get('agentCardUrl') || '').trim()\r\n      payload.preferredTransport = data.get('preferredTransport')\r\n      payload.authType = data.get('authType')\r\n      payload.authHeaderName = String(data.get('authHeaderName') || '').trim()\r\n      const authValue = String(data.get('authValue') || '')\r\n      if (authValue) payload.authValue = authValue\r\n      payload.timeoutMs = Number(data.get('timeoutMs')) * 1000\r\n    }\r\n    await api('/v1/admin/agents/' + encodeURIComponent(id), { method: 'PUT', body: payload })\r\n    closeDrawer()\r\n    await loadAll(true)\r\n    render()\r\n    toast(editing ? '智能体已更新' : '智能体已添加')\r\n  })\r\n  const protocolSelect = drawerFormElements().protocol\r\n  const authSelect = drawerFormElements().authType\r\n  const sync = () => {\r\n    document.querySelectorAll('#drawer-form [data-protocol-section]').forEach((section) => {\r\n      section.classList.toggle('hidden', section.dataset.protocolSection !== protocolSelect.value)\r\n      section.querySelectorAll('input,select,textarea').forEach((field) => { field.disabled = section.classList.contains('hidden') })\r\n    })\r\n    if (protocolSelect.value === 'a2a') {\r\n      const auth = authSelect.value\r\n      document.querySelector('#drawer-form [data-auth-header]').classList.toggle('hidden', auth !== 'header')\r\n      document.querySelector('#drawer-form [data-auth-value]').classList.toggle('hidden', auth === 'none')\r\n      document.querySelector('#drawer-form [data-auth-value-label]').textContent = auth === 'bearer' ? 'Bearer Token' : '认证凭据'\r\n    }\r\n  }\r\n  protocolSelect.onchange = sync\r\n  authSelect.onchange = sync\r\n  sync()\r\n}\r\n\r\nfunction drawerFormElements() {\r\n  return byId('drawer-form').elements\r\n}\r\n\r\nexport function openWorkspaceDrawer(index) {\r\n  const editing = Number.isInteger(index)\r\n  const current = editing ? state.config.workspaceRoots[index] : ''\r\n  openDrawer(editing ? '编辑工作区' : '添加工作区', '<div class=\"field\"><label for=\"f-path\">允许访问的根目录</label><input id=\"f-path\" name=\"path\" value=\"' + escapeHtml(current) + '\" required></div>', editing ? '保存修改' : '添加工作区', async (form) => {\r\n    const roots = state.config.workspaceRoots.slice()\r\n    const value = String(new FormData(form).get('path') || '').trim()\r\n    if (editing) roots[index] = value\r\n    else roots.push(value)\r\n    const result = await api('/v1/admin/config/workspace-roots', { method: 'PUT', body: { workspaceRoots: roots } })\r\n    state.config = result\r\n    closeDrawer()\r\n    render()\r\n    toast(editing ? '工作区已更新' : '工作区已添加')\r\n  })\r\n}\r\n\r\nexport function openKeyDrawer() {\r\n  const scopeRows = state.config.agents.map((agent) => '<label class=\"checkbox\"><input type=\"checkbox\" name=\"agentId\" value=\"' + escapeHtml(agent.id) + '\">' + escapeHtml(agent.name) + ' <span class=\"muted\">(' + escapeHtml(agent.protocol.toUpperCase()) + ')</span></label>').join('')\r\n  const body = '<div class=\"field\"><label for=\"f-name\">名称</label><input id=\"f-name\" name=\"name\" required autocomplete=\"off\" placeholder=\"例如：开发客户端\"></div><div class=\"field\"><label class=\"checkbox\"><input id=\"all-agents\" name=\"allAgents\" type=\"checkbox\" checked>允许访问全部智能体</label></div><div id=\"agent-scope\" class=\"agent-scope hidden\">' + (scopeRows || '<span class=\"muted\">尚未配置智能体。</span>') + '</div><div class=\"field\"><label for=\"f-customSecret\">自定义密钥（可选）</label><input id=\"f-customSecret\" name=\"customSecret\" minlength=\"16\" autocomplete=\"off\" placeholder=\"留空则自动生成 nx_sk_ 密钥\"></div>'\r\n  openDrawer('创建 API 密钥', body, '创建 API 密钥', async (form) => {\r\n    const data = new FormData(form)\r\n    const allAgents = data.get('allAgents') === 'on'\r\n    const agentIds = data.getAll('agentId').map(String)\r\n    if (!allAgents && !agentIds.length) throw new Error('请至少选择一个智能体')\r\n    const customSecret = String(data.get('customSecret') || '').trim()\r\n    const result = await api('/v1/admin/api-keys', {\r\n      method: 'POST',\r\n      body: {\r\n        name: String(data.get('name') || '').trim(),\r\n        scope: { allAgents, agentIds },\r\n        customSecret: customSecret || undefined\r\n      }\r\n    })\r\n    state.apiKeys.unshift(result.key)\r\n    showSecret('API 密钥已创建', result.secret)\r\n    render()\r\n  })\r\n  const all = byId('all-agents')\r\n  all.onchange = () => byId('agent-scope').classList.toggle('hidden', all.checked)\r\n}\r\n\r\nexport function showSecret(title, secret) {\r\n  openDrawer(title, '<div class=\"secret-box\"><span class=\"muted\">请立即复制；之后可在密钥列表中再次显示。</span><code class=\"secret-value\">' + escapeHtml(secret) + '</code><button class=\"button\" type=\"button\" id=\"copy-secret\">' + icons.copy + '复制</button></div>', '', null)\r\n  byId('copy-secret').onclick = async () => {\r\n    try {\r\n      await copySecret(secret)\r\n      toast('API 密钥已复制')\r\n    } catch (error) { toast(error.message, true) }\r\n  }\r\n}\r\n\r\nexport async function copySecret(secret) {\r\n  if (navigator.clipboard && window.isSecureContext) {\r\n    try {\r\n      await navigator.clipboard.writeText(secret)\r\n      return\r\n    } catch {}\r\n  }\r\n  const temporary = document.createElement('textarea')\r\n  temporary.value = secret\r\n  temporary.setAttribute('readonly', '')\r\n  temporary.style.position = 'fixed'\r\n  temporary.style.opacity = '0'\r\n  temporary.style.pointerEvents = 'none'\r\n  document.body.appendChild(temporary)\r\n  temporary.select()\r\n  const copied = document.execCommand('copy')\r\n  temporary.remove()\r\n  if (!copied) throw new Error('无法自动复制，请在“显示完整密钥”中手动复制。')\r\n}\r\n\r\nexport function openPasswordDrawer() {\r\n  openDrawer('修改控制台密码', '<div class=\"field\"><label for=\"f-currentPassword\">当前密码</label><input id=\"f-currentPassword\" name=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" required></div><div class=\"field\"><label for=\"f-newPassword\">新密码</label><input id=\"f-newPassword\" name=\"newPassword\" type=\"password\" minlength=\"12\" autocomplete=\"new-password\" required></div><div class=\"field\"><label for=\"f-confirmPassword\">确认新密码</label><input id=\"f-confirmPassword\" name=\"confirmPassword\" type=\"password\" minlength=\"12\" autocomplete=\"new-password\" required></div>', '修改密码', async (form) => {\r\n    const data = new FormData(form)\r\n    await api('/v1/admin/password', { method: 'PUT', body: { currentPassword: String(data.get('currentPassword') || ''), newPassword: String(data.get('newPassword') || ''), confirmPassword: String(data.get('confirmPassword') || '') } })\r\n    closeDrawer()\r\n    showLogin()\r\n    toast('控制台密码已修改，请重新登录。')\r\n  })\r\n}\r\n\r\nexport function openKeyScopeDrawer(key) {\r\n  const selectedIds = new Set(key.scope.agentIds || [])\r\n  const scopeRows = state.config.agents.map((agent) => '<label class=\"checkbox\"><input type=\"checkbox\" name=\"agentId\" value=\"' + escapeHtml(agent.id) + '\"' + checked(selectedIds.has(agent.id)) + '>' + escapeHtml(agent.name) + ' <span class=\"muted\">(' + escapeHtml(agent.protocol.toUpperCase()) + ')</span></label>').join('')\r\n  const body = '<div class=\"field\"><label class=\"checkbox\"><input id=\"edit-all-agents\" name=\"allAgents\" type=\"checkbox\"' + checked(key.scope.allAgents) + '>允许访问全部智能体</label></div><div id=\"edit-agent-scope\" class=\"agent-scope' + (key.scope.allAgents ? ' hidden' : '') + '\">' + (scopeRows || '<span class=\"muted\">尚未配置智能体。</span>') + '</div>'\r\n  openDrawer('编辑 API 密钥授权范围', body, '保存授权范围', async (form) => {\r\n    const data = new FormData(form)\r\n    const allAgents = data.get('allAgents') === 'on'\r\n    const agentIds = data.getAll('agentId').map(String)\r\n    if (!allAgents && !agentIds.length) throw new Error('请至少选择一个智能体')\r\n    await api('/v1/admin/api-keys/' + encodeURIComponent(key.id), { method: 'PATCH', body: { scope: { allAgents, agentIds } } })\r\n    closeDrawer()\r\n    await reloadKeys()\r\n    toast('API 密钥授权范围已更新')\r\n  })\r\n  const all = byId('edit-all-agents')\r\n  all.onchange = () => byId('edit-agent-scope').classList.toggle('hidden', all.checked)\r\n}\r\n\r\nexport function openRenameKeyDrawer(key) {\r\n  openDrawer('重命名 API 密钥', '<div class=\"field\"><label for=\"f-key-name\">名称</label><input id=\"f-key-name\" name=\"name\" value=\"' + escapeHtml(key.name) + '\" required autocomplete=\"off\"></div>', '保存名称', async (form) => {\r\n    const name = String(new FormData(form).get('name') || '').trim()\r\n    if (name === key.name) { closeDrawer(); return }\r\n    await api('/v1/admin/api-keys/' + encodeURIComponent(key.id), { method: 'PATCH', body: { name } })\r\n    closeDrawer()\r\n    await reloadKeys()\r\n    toast('API 密钥已重命名')\r\n  })\r\n  const input = byId('f-key-name')\r\n  if (input) setTimeout(() => input.select(), 0)\r\n}\r\n\r\nexport async function reloadKeys() {\r\n  const value = await api('/v1/admin/api-keys')\r\n  state.apiKeys = value.apiKeys || []\r\n  render()\r\n}\r\n\r\n/* ── Key action menu ──────────────────────────────────────────────── */\r\n\r\nexport function toggleKeyActionMenu(anchor, id) {\r\n  if (!keyActionMenu.classList.contains('hidden') && keyActionMenu.dataset.keyId === id) {\r\n    closeKeyActionMenu()\r\n    return\r\n  }\r\n  closeKeyActionMenu()\r\n  keyActionMenu.dataset.keyId = id\r\n  keyActionMenu.innerHTML =\r\n    '<button type=\"button\" role=\"menuitem\" data-key-action=\"reveal\" data-key-id=\"' + escapeHtml(id) + '\">' + icons.reveal + '<span>显示完整密钥</span></button>' +\r\n    '<button type=\"button\" role=\"menuitem\" data-key-action=\"scope\" data-key-id=\"' + escapeHtml(id) + '\">' + icons.scope + '<span>编辑授权范围</span></button>' +\r\n    '<button type=\"button\" role=\"menuitem\" data-key-action=\"regenerate\" data-key-id=\"' + escapeHtml(id) + '\">' + icons.regenerate + '<span>重新生成密钥</span></button>' +\r\n    '<button type=\"button\" role=\"menuitem\" class=\"danger-text\" data-key-action=\"delete\" data-key-id=\"' + escapeHtml(id) + '\">' + icons.trash + '<span>删除密钥</span></button>'\r\n  keyActionMenu.classList.remove('hidden')\r\n  anchor.setAttribute('aria-expanded', 'true')\r\n  const anchorRect = anchor.getBoundingClientRect()\r\n  const menuRect = keyActionMenu.getBoundingClientRect()\r\n  const left = Math.max(8, Math.min(window.innerWidth - menuRect.width - 8, anchorRect.right - menuRect.width))\r\n  const below = anchorRect.bottom + 6\r\n  const top = below + menuRect.height <= window.innerHeight - 8\r\n    ? below\r\n    : Math.max(8, anchorRect.top - menuRect.height - 6)\r\n  keyActionMenu.style.left = left + 'px'\r\n  keyActionMenu.style.top = top + 'px'\r\n}\r\n\r\nexport function closeKeyActionMenu() {\r\n  keyActionMenu.classList.add('hidden')\r\n  keyActionMenu.innerHTML = ''\r\n  keyActionMenu.dataset.keyId = ''\r\n  document.querySelectorAll('[data-key-menu][aria-expanded=\"true\"]').forEach((button) => button.setAttribute('aria-expanded', 'false'))\r\n}\r\n\r\n",
    "screens": "import { state } from './state.js'\nimport { setupScreen, loginScreen, appRoot, byId } from './dom.js'\nimport { api } from './api.js'\nimport { toast } from './toast.js'\nimport { loadAll } from './data.js'\nimport { render } from './render.js'\nimport { applyTheme } from './theme.js'\n\nfunction showOnly(element) {\n  setupScreen.classList.add('hidden')\n  loginScreen.classList.add('hidden')\n  appRoot.classList.add('hidden')\n  element.classList.remove('hidden')\n}\n\nexport function showLogin() {\n  state.authenticated = false\n  showOnly(loginScreen)\n  byId('login-form').reset()\n}\n\nexport async function boot() {\n  applyTheme(localStorage.getItem('agent-nexus-theme') || 'system')\n  try {\n    const bootstrap = await api('/v1/bootstrap/status')\n    if (bootstrap.adminSetupRequired) {\n      showOnly(setupScreen)\n      return\n    }\n    const auth = await api('/v1/admin/auth/status')\n    if (!auth.authenticated) {\n      showLogin()\n      return\n    }\n    await enterApp()\n  } catch (error) {\n    showLogin()\n    toast(error.message, true)\n  }\n}\n\nexport async function enterApp() {\n  state.authenticated = true\n  showOnly(appRoot)\n  await loadAll()\n  render()\n}\n\n",
    "state": "export const state = {\n  page: 'overview',\n  config: { workspaceRoots: [], driverKinds: [], agents: [] },\n  readiness: [],\n  apiKeys: [],\n  runs: [],\n  runTotal: 0,\n  sessions: 0,\n  search: '',\n  protocol: 'all',\n  status: 'all',\n  runSearch: '',\n  runAgent: 'all',\n  runStatus: 'all',\n  authenticated: false\n}\n\nexport const pageMeta = {\n  overview: '总览',\n  runs: '运行记录',\n  agents: '智能体',\n  workspaces: '工作区',\n  keys: 'API 密钥',\n  settings: '运行设置'\n}\n\n",
    "theme": "import { byId } from './dom.js'\n\nexport function applyTheme(preference) {\n  const theme = preference === 'system'\n    ? (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')\n    : preference\n  document.documentElement.dataset.theme = theme\n  const select = byId('theme-select')\n  if (select) select.value = preference\n}\n\n",
    "toast": "import { byId } from './dom.js'\n\nexport function toast(message, error) {\n  const item = document.createElement('div')\n  item.className = 'toast' + (error ? ' error' : '')\n  item.textContent = message\n  byId('toast-region').appendChild(item)\n  setTimeout(() => item.remove(), 4200)\n}\n\nexport async function runAction(task) {\n  try { await task() } catch (error) { toast(error.message, true) }\n}\n\n"
}
